 * Reading and splitting the three input documents.
 */

export const SEPARATOR = '%%%'

/**
 * Split raw input text into lines: split on newlines and drop the empty tail
 * that a trailing newline leaves behind.
 */
export function toLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Split a list of lines into documents on lines that are exactly `%%%`.
 * Every other line belongs to the document it sits in. Returns the list of
 * documents, which is `null` when there are not exactly three.
 */
export function splitDocuments(lines) {
  const documents = [[]]
  for (const line of lines) {
    if (line === SEPARATOR) documents.push([])
    else documents[documents.length - 1].push(line)
  }
  return documents.length === 3 ? documents : null
}
"}

