{"file_path":"src/diff.js","content":"/**
 * Comparing one side against the base with a longest common subsequence over
 * whole lines, compared as exact strings.
 */

/**
 * The matches of the longest common subsequence of `side` and `base`, as pairs
 * of indices. When several subsequences are equally long the one whose matches
 * come earliest is taken: walking both documents from the start, a match is
 * taken whenever the two current lines are equal, and otherwise the side whose
 * remaining subsequence is at least as long as the other's is advanced,
 * preferring to advance the base when they tie.
 */
export function longestCommonSubsequence(side, base) {
  const n = side.length
  const m = base.length
  const width = m + 1
  // lengths[i][j] is the length of the longest common subsequence of the
  // suffixes side[i..] and base[j..].
  const lengths = new Int32Array((n + 1) * width)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      const dropSide = lengths[(i + 1) * width + j]
      const dropBase = lengths[i * width + j + 1]
      lengths[i * width + j] =
        side[i] === base[j]
          ? lengths[(i + 1) * width + j + 1] + 1
          : Math.max(dropSide, dropBase)
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (side[i] === base[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (lengths[i * width + j + 1] >= lengths[(i + 1) * width + j]) {
      j++
    } else {
      i++
    }
  }
  return matches
}

/**
 * Every stretch the common subsequence does not cover, as a run of base lines
 * replaced by a run of the side's lines. An insertion replaces zero base lines
 * and a deletion inserts zero lines.
 */
export function changes(side, base) {
  const matches = longestCommonSubsequence(side, base)
  const result = []
  let sideIndex = 0
  let baseIndex = 0

  const emit = (sideEnd, baseEnd) => {
    if (sideIndex < sideEnd || baseIndex < baseEnd) {
      result.push({
        baseStart: baseIndex,
        baseEnd,
        sideStart: sideIndex,
        sideEnd,
      })
    }
  }

  for (const [sideMatch, baseMatch] of matches) {
    emit(sideMatch, baseMatch)
    sideIndex = sideMatch + 1
    baseIndex = baseMatch + 1
  }
  emit(side.length, base.length)

  return result
}
"}

