{"file_path":"src/merge.js","content":"/**
 * Gathering the changes of both sides into regions and resolving them.
 */

import { changes } from './diff.js'

/**
 * The regions of the merge, in base order. Each region is either
 * `{ kind: 'stable', lines }` or a changed region carrying the lines of both
 * sides and of the base, resolved to one of `mine`, `theirs`, `both` or
 * `conflict`.
 */
export function mergeRegions(mine, base, theirs) {
  const gathered = [
    ...changes(mine, base).map(change => ({ ...change, side: 'mine' })),
    ...changes(theirs, base).map(change => ({ ...change, side: 'theirs' })),
  ]
  // Ordered by where they start in the base, mine before theirs at a tie.
  gathered.sort(
    (a, b) => a.baseStart - b.baseStart || (a.side === b.side ? 0 : a.side === 'mine' ? -1 : 1),
  )

  const regions = []
  let baseCursor = 0
  let index = 0
  while (index < gathered.length) {
    const first = gathered[index]
    let regionStart = first.baseStart
    let regionEnd = first.baseEnd
    const taken = [first]
    index++
    // Keep absorbing the next change while it starts at or before the end.
    while (index < gathered.length && gathered[index].baseStart <= regionEnd) {
      regionEnd = Math.max(regionEnd, gathered[index].baseEnd)
      taken.push(gathered[index])
      index++
    }

    if (regionStart > baseCursor) {
      regions.push({ kind: 'stable', lines: base.slice(baseCursor, regionStart) })
    }
    regions.push(
      resolve(
        sideLines(mine, base, taken, 'mine', regionStart, regionEnd),
        base.slice(regionStart, regionEnd),
        sideLines(theirs, base, taken, 'theirs', regionStart, regionEnd),
      ),
    )
    baseCursor = regionEnd
  }
  if (baseCursor < base.length) {
    regions.push({ kind: 'stable', lines: base.slice(baseCursor) })
  }
  return regions
}

/**
 * The replacement one side makes over a region: it runs from the smallest
 * start of that side's own changes, moved back by however far the region
 * begins before those changes do in the base, to the largest end of its own
 * changes, moved forward by however far the region ends after them. A side
 * with no change in the region leaves the base lines as they are.
 */
function sideLines(document, base, taken, side, regionStart, regionEnd) {
  const own = taken.filter(change => change.side === side)
  if (own.length === 0) return base.slice(regionStart, regionEnd)

  let baseStart = Infinity
  let baseEnd = -Infinity
  let start = Infinity
  let end = -Infinity
  for (const change of own) {
    if (change.baseStart < baseStart) {
      baseStart = change.baseStart
      start = change.sideStart
    }
    if (change.baseEnd > baseEnd) {
      baseEnd = change.baseEnd
      end = change.sideEnd
    }
  }
  return document.slice(start - (baseStart - regionStart), end + (regionEnd - baseEnd))
}

function resolve(mineLines, baseLines, theirsLines) {
  const region = { kind: 'changed', mineLines, baseLines, theirsLines }
  if (same(mineLines, theirsLines)) return { ...region, kind: 'both', lines: mineLines }
  if (same(mineLines, baseLines)) return { ...region, kind: 'theirs', lines: theirsLines }
  if (same(theirsLines, baseLines)) return { ...region, kind: 'mine', lines: mineLines }
  return { ...region, kind: 'conflict' }
}

function same(a, b) {
  return a.length === b.length && a.every((line, index) => line === b[index])
}
"}

