/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'fs'

const mode = process.argv[2]

// Validate mode
if (!['merge', 'merge2', 'regions'].includes(mode)) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
  process.exit(2)
}

// Read all input
const input = readFileSync(0, 'utf8')

// Split documents
const parts = input.split(/%%%\n?/)
if (parts.length !== 3) {
  process.stderr.write('error: expected three parts separated by %%%\n')
  process.exit(2)
}

// Parse documents into lines, removing trailing empty line if present
function parseDocument(text) {
  if (!text) return []
  const lines = text.split('\n')
  // Remove trailing empty string if text ended with newline
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }
  return lines
}

const mine = parseDocument(parts[0])
const base = parseDocument(parts[1])
const theirs = parseDocument(parts[2])

// Compute greedy LCS (longest common subsequence)
function computeGreedyLCS(a, b) {
  const matches = []
  let i = 0, j = 0

  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      matches.push({ aIdx: i, bIdx: j })
      i++
      j++
    } else {
      const remainA = a.length - i
      const remainB = b.length - j

      // Advance side with more remaining content, prefer base (first arg) on tie
      if (remainA >= remainB) {
        i++
      } else {
        j++
      }
    }
  }

  return matches
}

// Identify changes between side and base
function identifyChanges(side, base) {
  const matches = computeGreedyLCS(side, base)

  const changes = []
  let sideIdx = 0
  let baseIdx = 0

  for (const match of matches) {
    // Add change for unmatched section before this match
    if (sideIdx < match.aIdx || baseIdx < match.bIdx) {
      changes.push({
        baseStart: baseIdx,
        baseEnd: match.bIdx,
        sideLines: side.slice(sideIdx, match.aIdx)
      })
    }

    sideIdx = match.aIdx + 1
    baseIdx = match.bIdx + 1
  }

  // Add any remaining unmatched content
  if (sideIdx < side.length || baseIdx < base.length) {
    changes.push({
      baseStart: baseIdx,
      baseEnd: base.length,
      sideLines: side.slice(sideIdx)
    })
  }

  return changes
}

// Reconstruct what a side looks like for a base range
function reconstructSideForBaseRange(side, base, matches, changes, start, end) {
  // Create maps for quick lookup
  const matchMap = {}
  for (const match of matches) {
    matchMap[match.bIdx] = match.aIdx
  }

  const changeMap = {}
  for (const change of changes) {
    changeMap[change.baseStart] = change
  }

  // Special case: if start == end, check for insertion at that position
  if (start === end) {
    if (changeMap[start] && changeMap[start].baseEnd === start) {
      // This is an insertion at this position
      return changeMap[start].sideLines
    }
    return []
  }

  const result = []
  let baseIdx = start

  while (baseIdx < end) {
    if (changeMap[baseIdx]) {
      const change = changeMap[baseIdx]
      result.push(...change.sideLines)
      baseIdx = change.baseEnd
    } else if (matchMap.hasOwnProperty(baseIdx)) {
      result.push(side[matchMap[baseIdx]])
      baseIdx++
    } else {
      baseIdx++
    }
  }

  return result
}

// Get changes for both sides
const mineMatches = computeGreedyLCS(mine, base)
const theirsMatches = computeGreedyLCS(theirs, base)
const mineChanges = identifyChanges(mine, base)
const theirsChanges = identifyChanges(theirs, base)

// Merge changes into regions
const allChanges = []
for (const change of mineChanges) {
  allChanges.push({ ...change, side: 'mine' })
}
for (const change of theirsChanges) {
  allChanges.push({ ...change, side: 'theirs' })
}

// Sort by base position, mine before theirs when same position
allChanges.sort((a, b) => {
  if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
  return a.side === 'mine' ? -1 : 1
})

// Group changes into regions
const regions = []

for (const change of allChanges) {
  const regionEnd = regions.length > 0 ? regions[regions.length - 1].baseEnd : 0

  // Add stable region if there's a gap
  if (change.baseStart > regionEnd) {
    regions.push({
      type: 'stable',
      baseStart: regionEnd,
      baseEnd: change.baseStart,
      mineChanges: [],
      theirsChanges: []
    })
  }

  // Add or extend conflict region
  if (regions.length > 0 && regions[regions.length - 1].type === 'conflict' &&
      change.baseStart <= regions[regions.length - 1].baseEnd) {
    // Extend current region
    regions[regions.length - 1].baseEnd = Math.max(regions[regions.length - 1].baseEnd, change.baseEnd)
  } else {
    // Start new region
    regions.push({
      type: 'conflict',
      baseStart: change.baseStart,
      baseEnd: change.baseEnd,
      mineChanges: [],
      theirsChanges: []
    })
  }

  if (change.side === 'mine') {
    regions[regions.length - 1].mineChanges.push(change)
  } else {
    regions[regions.length - 1].theirsChanges.push(change)
  }
}

// Add final stable region
if (regions.length > 0 && regions[regions.length - 1].baseEnd < base.length) {
  regions.push({
    type: 'stable',
    baseStart: regions[regions.length - 1].baseEnd,
    baseEnd: base.length,
    mineChanges: [],
    theirsChanges: []
  })
} else if (regions.length === 0 && base.length > 0) {
  regions.push({
    type: 'stable',
    baseStart: 0,
    baseEnd: base.length,
    mineChanges: [],
    theirsChanges: []
  })
}

// Resolve regions
const resolved = []
let hasConflict = false

for (const region of regions) {
  if (region.type === 'stable') {
    resolved.push({
      type: 'stable',
      lines: base.slice(region.baseStart, region.baseEnd)
    })
  } else {
    const baseLines = base.slice(region.baseStart, region.baseEnd)
    const mineLines = reconstructSideForBaseRange(mine, base, mineMatches, mineChanges, region.baseStart, region.baseEnd)
    const theirsLines = reconstructSideForBaseRange(theirs, base, theirsMatches, theirsChanges, region.baseStart, region.baseEnd)

    // Check for conflict
    const mineStr = JSON.stringify(mineLines)
    const theirsStr = JSON.stringify(theirsLines)
    const baseStr = JSON.stringify(baseLines)

    if (mineStr === theirsStr) {
      // Same change on both sides
      resolved.push({
        type: 'both',
        lines: mineLines
      })
    } else if (mineStr === baseStr) {
      // Only theirs changed
      resolved.push({
        type: 'theirs',
        lines: theirsLines
      })
    } else if (theirsStr === baseStr) {
      // Only mine changed
      resolved.push({
        type: 'mine',
        lines: mineLines
      })
    } else {
      // Conflict!
      hasConflict = true
      resolved.push({
        type: 'conflict',
        mineLines,
        baseLines,
        theirsLines
      })
    }
  }
}

// Output
if (mode === 'merge' || mode === 'merge2') {
  const output = []

  for (const section of resolved) {
    if (section.type === 'stable' || section.type === 'both' || section.type === 'mine' || section.type === 'theirs') {
      output.push(...section.lines)
    } else if (section.type === 'conflict') {
      output.push('<<<<<<< mine')
      output.push(...section.mineLines)

      if (mode === 'merge') {
        output.push('||||||| base')
        output.push(...section.baseLines)
      }

      output.push('=======')
      output.push(...section.theirsLines)
      output.push('>>>>>>> theirs')
    }
  }

  process.stdout.write(output.map(line => line + '\n').join(''))
  process.exit(hasConflict ? 1 : 0)
} else if (mode === 'regions') {
  const output = []

  for (const section of resolved) {
    if (section.type === 'stable') {
      output.push(`stable ${section.lines.length}`)
    } else if (section.type === 'mine') {
      output.push(`mine ${section.lines.length}`)
    } else if (section.type === 'theirs') {
      output.push(`theirs ${section.lines.length}`)
    } else if (section.type === 'both') {
      output.push(`both ${section.lines.length}`)
    } else if (section.type === 'conflict') {
      output.push(`conflict mine=${section.mineLines.length} base=${section.baseLines.length} theirs=${section.theirsLines.length}`)
    }
  }

  process.stdout.write(output.join('\n') + (output.length ? '\n' : ''))
  process.exit(hasConflict ? 1 : 0)
}

