cat > "$SP/inv.mjs" <<EOF
import { mergeRegions } from '$PWD/src/merge.js'
const A='abcXY'
const rnd=n=>Array.from({length:Math.floor(Math.random()*n)},()=>A[Math.floor(Math.random()*A.length)])
const flat=rs=>rs.flatMap(r=>r.kind==='conflict'?null:r.lines)
const eq=(a,b)=>a.length===b.length&&a.every((x,i)=>x===b[i])
for(let t=0;t<50000;t++){
 const base=rnd(7), mine=rnd(7), theirs=rnd(7)
 for(const [m,o,th,expect] of [[mine,base,base,mine],[base,base,theirs,theirs],[mine,base,mine,mine]]){
  const rs=mergeRegions(m,o,th)
  if(rs.some(r=>r.kind==='conflict')) throw new Error('unexpected conflict '+JSON.stringify([m,o,th]))
  const got=flat(rs)
  if(!eq(got,expect)) throw new Error('bad merge '+JSON.stringify([m,o,th,got,expect]))
 }
 // general: region base lines must tile base exactly
 const rs=mergeRegions(mine,base,theirs)
 const tiled=rs.flatMap(r=>r.kind==='stable'?r.lines:r.baseLines)
 if(!eq(tiled,base)) throw new Error('base not tiled '+JSON.stringify([mine,base,theirs]))
}
console.log('invariants ok')
EOF
node "$SP/inv.mjs"","description":"Randomized merge invariant checks"}

